    app.use('/api/*', cors({ origin: ['http://localhost:4347'] }));
    app.get('/api/dashboard', (context) => {
        try {
            const days = Number(context.req.query('days') ?? 30);
            const modelParams = context.req.queries('models');
            const models = modelParams?.length ? modelParams : undefined;
            const providers = context.req.queries('providers');
            return context.json(database.dashboard(days, models, providers));
        }
        catch (error) {
            const message = error instanceof Error ? error.message : 'Unbekannter Lesefehler';
            return context.json({ error: `Dashboard-Daten konnten nicht gelesen werden: ${message}` }, 500);
        }
    });
    app.post('/api/sync', (context) => {
        try {
            return context.json(database.sync());
        }
        catch (error) {
            const message = error instanceof Error ? error.message : 'Unbekannter Importfehler';
            return context.json({ error: `OpenCode-Daten konnten nicht importiert werden: ${message}` }, 500);
        }
    });
    app.get('/api/pricing', (context) => context.json(database.pricing()));
    app.put('/api/pricing/reference', async (context) => {
        let body;
        try {
            body = await context.req.json();
        }
        catch {
            return context.json({ error: 'Ungültiger JSON-Body.' }, 400);
        }
        if (typeof body?.model !== 'string' || typeof body.provider !== 'string' || (body.openRouterId !== null && typeof body.openRouterId !== 'string')) {
            return context.json({ error: 'Modell, Anbieter und eine OpenRouter-ID (oder null zum Entfernen) sind erforderlich.' }, 400);
        }
        try {
            database.setPricingReference(body.model, body.provider, body.openRouterId);
            return context.body(null, 204);
        }
        catch (error) {
            if (error instanceof PricingReferenceError)
                return context.json({ error: error.message }, error.status);
            throw error;
        }
    });
    app.post('/api/pricing/refresh', async (context) => {
        const result = await database.refreshOpenRouterPricing({ force: context.req.query('ifStale') !== '1' });
        return context.json(result, result.status === 'failed' ? 502 : 200);
    });
    app.put('/api/pricing', async (context) => {
        try {
            const body = await context.req.json();
            const prices = Array.isArray(body.prices) ? body.prices : [];
            const providers = Array.isArray(body.providers) ? body.providers : [];
            if (!prices.every(isPriceInput) || !providers.every(isPricingSource))
                return context.json({ error: 'Ungültige Preisdaten.' }, 400);
            return context.json(database.savePricing(prices, providers));
        }
        catch (error) {
            const message = error instanceof Error ? error.message : 'Preise konnten nicht gespeichert werden.';
            return context.json({ error: message }, 400);
        }
    });
    app.delete('/api/pricing/all', (context) => context.json(database.resetAllPricing()));
    app.delete('/api/pricing', async (context) => {
        try {
            const body = await context.req.json();
            if (typeof body.model !== 'string' || typeof body.provider !== 'string' || !body.model.trim() || !body.provider.trim()) {
                return context.json({ error: 'Ungültiges Anbieter-Modell.' }, 400);
            }
            return context.json(database.resetPricing(body.model, body.provider));
        }
        catch (error) {
            const message = error instanceof Error ? error.message : 'Preisdaten konnten nicht gelöscht werden.';
            return context.json({ error: message }, 400);
        }
    });
    app.post('/api/pricing/import', async (context) => {
        try {
            const body = await context.req.json();
            if (!body || typeof body !== 'object')
                return context.json({ error: 'Ungültiges Importformat.' }, 400);
            const { prices, providers } = body;
            const normalizedPrices = Array.isArray(prices) ? prices : prices ? [prices] : [];
            const normalizedProviders = Array.isArray(providers) ? providers : providers ? [providers] : [];
            if (!normalizedPrices.every(isPriceInput) || !normalizedProviders.every(isPricingSource)) {
                return context.json({ error: 'Der Import muss gültige Preise und optionale Preisquellen enthalten.' }, 400);
            }
            return context.json(database.savePricing(normalizedPrices, normalizedProviders));
        }
        catch (error) {
            const message = error instanceof Error ? error.message : 'Preise konnten nicht importiert werden.';
            return context.json({ error: message }, 400);
        }
    });
    app.get('/api/settings/export', (context) => context.json(database.settingsExport()));
    app.post('/api/settings/import/preview', async (context) => {
        try {
            const settings = await context.req.json();
            return context.json(database.previewSettingsImport(settings));
        }
        catch (error) {
            const message = error instanceof Error ? error.message : 'Settings-Datei konnte nicht geprüft werden.';
            return context.json({ error: message }, 400);
        }
    });
    app.post('/api/settings/import', async (context) => {
        try {
            const body = await context.req.json();
            if (!body.strategy || typeof body.strategy !== 'object')
                return context.json({ error: 'Eine Importstrategie ist erforderlich.' }, 400);
            const { priceConflict } = body.strategy;
            if (priceConflict !== 'abort' && priceConflict !== 'skip' && priceConflict !== 'overwrite') {
                return context.json({ error: 'Ungültige Importstrategie.' }, 400);
            }
            return context.json(database.importSettings(body.settings, { priceConflict }));
        }
        catch (error) {
            const message = error instanceof Error ? error.message : 'Settings-Datei konnte nicht importiert werden.';
            return context.json({ error: message }, 400);
        }
    });
    app.get('/api/health', (context) => {
        pruneInstances();
        return context.json({
            status: 'ok',
            version: packageVersion,
            pid: process.pid,
            parentPid,
            managed: managedByPlugin,
            instances: [...instances],
            dashboardDbPath: dashboardDatabasePath,
            opencodeDbPath: openCodeDatabasePath,
        });
    });
    app.get('/api/version', (context) => context.json({ version: packageVersion }));
    app.post('/api/instances', async (context) => {
        try {
            const body = await context.req.json();
            const pid = parseInstancePid(body.pid);
            if (pid === undefined)
                return context.json({ error: 'Ungültige Prozess-ID.' }, 400);
            instances.add(pid);
            return context.json({ status: 'ok', instances: instances.size });
        }
        catch {
            return context.json({ error: 'Ungültige Prozess-ID.' }, 400);
        }
    });
    app.get('*', (context) => {
        const path = context.req.path;
        if (path.startsWith('/api/'))
            return context.json({ error: 'Nicht gefunden.' }, 404);
        const file = resolvePublicFile(path);
        if (!file) {
            return context.text(path === '/' ? 'Dashboard-Frontend nicht gefunden. Bitte zuerst das Frontend bauen und nach backend/public kopieren.' : 'Nicht gefunden.', 404);
        }
        return servePublicFile(context, file);
    });
    app.notFound((context) => context.req.path.startsWith('/api/') ? context.json({ error: 'Nicht gefunden.' }, 404) : context.text('Nicht gefunden.', 404));
    return app;
}
export function startServer(options) {
    const database = new DashboardDatabase();
    const app = createApp(database);
    const pollImport = () => {
        try {
            database.syncIfChanged();
        }
        catch (error) {
            console.warn('opencode-token-ledger: Automatischer Import fehlgeschlagen:', error instanceof Error ? error.message : error);
        }
    };
    let importTimer;
    const server = serve({ fetch: app.fetch, port: options.port, hostname: options.hostname }, (info) => {
        pollImport();
        importTimer = setInterval(pollImport, IMPORT_CHECK_INTERVAL_MS).unref();
        console.log(`opencode-token-ledger: http://localhost:${info.port}`);
    });
    server.once('close', () => {
        clearInterval(importTimer);
        database.close();
    });
    watchInstances(server);
    return server;
}
function isPriceInput(value) {
    if (!value || typeof value !== 'object')
        return false;
    const price = value;
    return typeof price.model === 'string' && typeof price.provider === 'string' && typeof price.inputUsdPerMillion === 'number' && typeof price.outputUsdPerMillion === 'number'
        && (price.cacheReadUsdPerMillion === undefined || price.cacheReadUsdPerMillion === null || typeof price.cacheReadUsdPerMillion === 'number')
        && (price.cacheWriteUsdPerMillion === undefined || price.cacheWriteUsdPerMillion === null || typeof price.cacheWriteUsdPerMillion === 'number')
        && (price.reasoningUsdPerMillion === undefined || price.reasoningUsdPerMillion === null || typeof price.reasoningUsdPerMillion === 'number');
}
function isPricingSource(value) {
    if (!value || typeof value !== 'object')
        return false;
    const source = value;
    return typeof source.provider === 'string' && (source.pricingUrl === undefined || source.pricingUrl === null || typeof source.pricingUrl === 'string');
}
